def test_wide_combining_overlap():
    # any char that is W/F but category Mn/Me/Cf should be 0
    found = False
    for cp in range(0x110000):
        c = chr(cp)
        if unicodedata.east_asian_width(c) in ('W', 'F') and unicodedata.category(c) in ('Mn', 'Me', 'Cf'):
            found = True
            assert display_width(c) == 0, hex(cp)
    if not found:
        assert True


