import unicodedata
from solution import display_width


def test_ascii():
    assert display_width('abc') == 3


def test_empty():
    assert display_width('') == 0


def test_hangul():
    assert display_width('한국') == 4


def test_cjk():
    assert display_width('中文') == 4


def test_fullwidth_letter():
    assert display_width('Ａ') == 2


def test_combining_mark():
    assert display_width('e\u0301') == 1


def test_enclosing_mark():
    assert unicodedata.category('\u20dd') == 'Me'
    assert display_width('a\u20dd') == 1


def test_zwj():
    assert display_width('a\u200db') == 2


def test_emoji_wide():
    assert display_width('😀') == 2


def test_emoji_zwj_sequence():
    # man ZWJ woman: 2 + 0 + 2
    assert display_width('👨\u200d👩') == 4


def test_mixed():
    assert display_width('a한b') == 4


def test_halfwidth_katakana_is_one():
    assert display_width('ｱ') == 1


def test_ambiguous_is_one():
    assert display_width('±') == 1


def test_space_and_punct():
    assert display_width(' !') == 2


def test_fullwidth_space():
    assert display_width('\u3000') == 2


def test_variation_selector_mn():
    # VS16 is Mn -> 0
    assert display_width('\ufe0f') == 0


def test_soft_hyphen_cf():
    assert display_width('\u00ad') == 0


def test_hangul_jamo_combining_cf_or_other():
    # compute expectation from the spec rules
    s = '\u1100\u1161'
    exp = 0
    for c in s:
        if unicodedata.category(c) in ('Mn', 'Me', 'Cf'):
            continue
        exp += 2 if unicodedata.east_asian_width(c) in ('W', 'F') else 1
    assert display_width(s) == exp


def test_control_char_one():
    # Cc is not listed as zero; "everything else takes 1"
    assert display_width('\n') == 1
    assert display_width('\t') == 1


def test_wide_combining_mark_zero():
    # Mn that is East Asian Wide? e.g. U+3099 is Mn (W)
    assert display_width('\u3099') == 0
